 ('materiel', 'Matériel', 'demo_materiel', 'mat_id', 'mat_proprietes', '{"libelle":"Matériel","titre":"[designation]","sous_titre":"[code] · [famille]","sections":[{"code":"identification","titre":"Identification","champs":["code","designation","famille","marque","numero_serie"]},{"code":"exploitation","titre":"Exploitation","champs":["etat","chantier","heures_utilisation","heures_revision","controle_ok"]},{"code":"achat","titre":"Achat","champs":["valeur_achat","date_achat"]},{"code":"notes","titre":"Notes","champs":["observations"]}],"champs":[{"code":"code","libelle":"Code","colonne":"mat_code","type":"texte","obligatoire":true,"longueur":10,"non_copie":true},{"code":"designation","libelle":"Désignation","colonne":"mat_designation","type":"texte","obligatoire":true,"longueur":100,"largeur":"plein"},{"code":"famille","libelle":"Famille","colonne":"mat_famille","type":"liste","obligatoire":true,"options":[{"valeur":"Engins","libelle":"Engins"},{"valeur":"Levage","libelle":"Levage"},{"valeur":"Outillage","libelle":"Outillage"},{"valeur":"Véhicules","libelle":"Véhicules"},{"valeur":"Coffrage","libelle":"Coffrage"}]},{"code":"marque","libelle":"Marque","colonne":"mat_marque","type":"texte","longueur":60},{"code":"numero_serie","libelle":"N° de série","colonne":"mat_numero_serie","type":"texte","longueur":40,"non_copie":true},{"code":"etat","libelle":"État","colonne":"mat_etat","type":"liste","obligatoire":true,"defaut":"DISPO","options":[{"valeur":"DISPO","libelle":"Disponible"},{"valeur":"CHANTIER","libelle":"En chantier"},{"valeur":"PANNE","libelle":"En panne"},{"valeur":"REBUT","libelle":"Rebut"}]},{"code":"chantier","libelle":"Chantier","colonne":"mat_chantier","type":"texte","longueur":100},{"code":"heures_utilisation","libelle":"Heures d''utilisation","colonne":"mat_heures","type":"nombre","obligatoire":true,"format":"99999","defaut":0},{"code":"heures_revision","libelle":"Révision tous les (heures)","colonne":"mat_heures_revision","type":"nombre","obligatoire":